import re


def calc_paren(expr):
    tokens = re.findall(r"\d+\.?\d*|[-+*/()]", expr.replace(" ", ""))
    pos = [0]

    def parse_expr():
        value = parse_term()
        while pos[0] < len(tokens) and tokens[pos[0]] in "+-":
            op = tokens[pos[0]]
            pos[0] += 1
            rhs = parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def parse_term():
        value = parse_factor()
        while pos[0] < len(tokens) and tokens[pos[0]] in "*/":
            op = tokens[pos[0]]
            pos[0] += 1
            rhs = parse_factor()
            value = value * rhs if op == "*" else value / rhs
        return value

    def parse_factor():
        tok = tokens[pos[0]]
        pos[0] += 1
        if tok == "(":
            value = parse_expr()
            pos[0] += 1  # 닫는 괄호
            return value
        return float(tok)

    return parse_expr()

